 "content": "from collections import Counter


def _runs(indices):
    if not indices:
        return []
    out = []
    start = prev = indices[0]
    for value in indices[1:]:
        if value != prev + 1:
            out.append((start, prev + 1))
            start = value
        prev = value
    out.append((start, prev + 1))
    return out


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_runs = _runs([r for r in range(h) if any(grid[r])])
    col_runs = _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])

    # Each nonzero rectangle is one patterned tile. Its center is the tile's symbol.
    tiles = {}
    counts = Counter()
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            if r1 - r0 < 3 or c1 - c0 < 3:
                continue
            r, c = (r0 + r1 - 1) // 2, (c0 + c1 - 1) // 2
            color = grid[r][c]
            tiles[(ri, ci)] = (r, c, color)
            counts[color] += 1

    # The four-occurrence symbols are the marked motifs; the more common tile
    # fill/background symbol is not connected.
    marked = {color for color, n in counts.items() if n == 4}
    by_row = {}
    by_col = {}
    for (ri, ci), (r, c, color) in tiles.items():
        if color in marked:
            by_row.setdefault((ri, color), []).append((ci, r, c))
            by_col.setdefault((ci, color), []).append((ri, r, c))

    # Join aligned equal symbols through blank separator cells, leaving tiles intact.
    for entries in by_row.values():
        entries.sort()
        for i, (_, r, c1) in enumerate(entries):
            for _, _, c2 in entries[i + 1:]:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if grid[r][c] == 0:
                        out[r][c] = grid[r][(c1 if c < c2 else c2)]
    for entries in by_col.values():
        entries.sort()
        for i, (_, r1, c) in enumerate(entries):
            for _, r2, _ in entries[i + 1:]:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
                    if grid[r][c] == 0:
                        out[r][c] = grid[r1][c]
    return out
