def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_runs = _runs([r for r in range(h) if any(grid[r])])
    col_runs = _runs([c for c in range(w) if any(grid[r][c] for r in range(h))])

    # Recover the repeated framed tiles and their non-frame colored motifs.
    tiles = {}
    for ri, (r0, r1) in enumerate(row_runs):
        for ci, (c0, c1) in enumerate(col_runs):
            if r1 - r0 < 3 or c1 - c0 < 3:
                continue
            perimeter = []
            for r in range(r0, r1):
                for c in range(c0, c1):
                    if r in (r0, r1 - 1) or c in (c0, c1 - 1):
                        if grid[r][c] != 0:
                            perimeter.append(grid[r][c])
            frame = Counter(perimeter).most_common(1)[0][0] if perimeter else 0
            motif = {}
            for r in range(r0 + 1, r1 - 1):
                for c in range(c0 + 1, c1 - 1):
                    color = grid[r][c]
                    if color not in (0, frame):
                        motif.setdefault(color, set()).add((r - r0, c - c0))
            if motif:
                tiles[(ri, ci)] = (r0, c0, motif)

    colors = {color for _, _, motifs in tiles.values() for color in motifs}
    # For each pair of matching motifs in a tile row, extend their shape across
    # intervening empty cells; preserve all existing tile pixels.
    for color in colors:
